const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        let res = 0;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const M = nextInt();

    const adj = Array.from({ length: N + 1 }, () => []);

    for (let i = 0; i < M; i++) {
        const u = nextInt();
        const v = nextInt();
        const c = nextInt();
        adj[u].push({ to: v, cost: c });
        adj[v].push({ to: u, cost: c });
    }

    const dist = new Array(N + 1).fill(Infinity);
    const visited = new Uint8Array(N + 1);

    dist[1] = 0;

    for (let i = 1; i <= N; i++) {
        let u = -1;
        let minD = Infinity;

        for (let j = 1; j <= N; j++) {
            if (!visited[j] && dist[j] < minD) {
                minD = dist[j];
                u = j;
            }
        }

        if (u === -1 || u === N) {
            break;
        }

        visited[u] = 1;

        const edges = adj[u];
        for (let j = 0; j < edges.length; j++) {
            const edge = edges[j];
            const v = edge.to;
            const w = edge.cost;
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
            }
        }
    }

    console.log(dist[N]);
}

solve();
